                with path.open("rb") as stream:
                    for chunk in iter(lambda: stream.read(_HASH_CHUNK_SIZE), b""):
                        digest.update(chunk)
            except OSError as error:
                raise PipelineContractError(
                    f"cannot hash tree file {path}: {error}"
                ) from error
    return digest.hexdigest()


